        var s = String(body == null ? '' : body);
        ZOMBIE_MARKER_RE.lastIndex = 0;
        var m;
        while ((m = ZOMBIE_MARKER_RE.exec(s)) !== null) {
            var sha = m[1];
            var n = parseInt(m[2], 10) || 0;
            var atMs = Date.parse(m[3]);
