                cur = map[sha] = { count: 0, lastAtMs: null };
            }
            if (n > cur.count) cur.count = n;
            if (!isNaN(atMs) && (cur.lastAtMs === null || atMs > cur.lastAtMs)) {
                cur.lastAtMs = atMs;
            }
