        assert.equal(live.classify({ active: false, newest: { status: 'queued', head_sha: HEAD } }),
            'running');
        assert.equal(live.classify({ active: false, newest: { status: 'completed', conclusion: null, head_sha: HEAD } }),
            'running');
    });

