    zombieMarks: zombieMarks,
    zombieMarkerLine: zombieMarkerLine,
    zombieCapOf: zombieCapOf,
    zombieWindowMsOf: zombieWindowMsOf,
    ZOMBIE_MARKER_RE: ZOMBIE_MARKER_RE,
    ACTIVE_RUN_STATES: ACTIVE_RUN_STATES
};

