            }
            try {
                // One jobs probe per stamp, shared by every stamped check
                // name (they all echo the same dispatched run).
                var linkBlock = stampLinkBlock(repoInfo, runUrl, conclusion);
                names.forEach(function (checkName) {
                    if (DRY) {
