        var marks = live.zombieMarks([line]);
        assert.equal(marks[HEAD].count, 1, 'the crash-loop cap reads the count');
        assert.equal(marks[HEAD].lastAtMs, null, 'the rate bound cannot fire — bounded churn, not a wedge');
    });
});

