            // checks:write on the repo the tick runs in. Swap GH_TOKEN for
            // the gh child exactly like silentUpdateBranch does, restore
            // after (sourceToken).
            var appToken = (RUN_JOB_PARAMS || {}).silentToken;
            var sourceTok = (RUN_JOB_PARAMS || {}).sourceToken;
